# PowerShell tab-completion for the `scent` CLI.
#
# Same limitation as scent.bash: SCENT's argument parser is hand-rolled,
# not generated by a framework, so this only completes command and flag
# *names* — it does not know which flags belong to which command, and it
# does not suggest file paths (PowerShell's own path completion already
# handles <path>).
#
# Install for this session only:
#   . completions/scent.ps1
#
# Install permanently: add the line above to your PowerShell profile
# ($PROFILE).

Register-ArgumentCompleter -Native -CommandName scent -ScriptBlock {
    param($wordToComplete, $commandAst, $cursorPosition)

    $tokens = $commandAst.CommandElements | ForEach-Object { $_.ToString() }
    $previous = if ($tokens.Count -ge 2) { $tokens[-2] } else { $null }

    if ($previous -eq '--format') {
        'human', 'json', 'sarif', 'table' |
            Where-Object { $_ -like "$wordToComplete*" } |
            ForEach-Object { [System.Management.Automation.CompletionResult]::new($_, $_, 'ParameterValue', $_) }
        return
    }

    if ($tokens.Count -le 2) {
        'analyze', 'rules', 'gate', '--help', '-h' |
            Where-Object { $_ -like "$wordToComplete*" } |
            ForEach-Object { [System.Management.Automation.CompletionResult]::new($_, $_, 'ParameterValue', $_) }
        return
    }

    '--format', '--max-critical', '--max-high', '--baseline', '--help', '-h' |
        Where-Object { $_ -like "$wordToComplete*" } |
        ForEach-Object { [System.Management.Automation.CompletionResult]::new($_, $_, 'ParameterValue', $_) }
}
